CREATE TABLE IF NOT EXISTS economic_graph_relationships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), from_type text NOT NULL, from_id uuid NOT NULL, relationship_type text NOT NULL, to_type text NOT NULL, to_id uuid NOT NULL, status text NOT NULL DEFAULT 'reported', confidence numeric(6,2), evidence_ref text, notes text, created_by text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(from_type,from_id,relationship_type,to_type,to_id));